// Short, source-checked practice translations; PDF pages use the file's page counter.
const olympBookTasks = [
 ['1.1(a)',20,'Измерения','Во сколько раз единица скорости СИ (м/с) больше единицы СГС (см/с)?',100,'раз','Секунда одинакова в обеих системах, а метр равен 100 см. Поэтому 1 м/с = 100 см/с.'],
 ['1.1(b)',20,'Измерения','Во сколько раз единица ускорения СИ больше единицы ускорения СГС?',100,'раз','1 м/с² = 100 см/с²: единица длины меняется в 100 раз, единица времени не меняется.'],
 ['1.1(c)',20,'Измерения','Сколько дин в одном ньютоне? Дина — единица силы СГС.',100000,'дин','1 Н = 1 кг·м/с². Подставим 1000 г и 100 см: получим 100 000 г·см/с², то есть 100 000 дин.'],
 ['1.1(d)',21,'Измерения','Сколько эргов в одном джоуле? Эрг — работа силы в одну дину на пути в один сантиметр.',10000000,'эрг','1 Дж = 1 Н·м = 100 000 дин · 100 см = 10 000 000 эрг.'],
 ['1.1(e)',21,'Давление','Сколько дин на квадратный сантиметр соответствует одному паскалю?',10,'дин/см²','1 Па = 1 Н/м². В числителе 100 000 дин, в знаменателе 10 000 см². Их отношение равно 10.'],
 ['1.2',21,'Давление','Человек массой 50 кг опирается на два каблука площадью по 5 см². Слон массой 4000 кг стоит на четырёх подошвах площадью по 0,2 м². Найди отношение давления каблука к давлению подошвы слона при равномерной нагрузке.',10,'раз','Сравниваем p = mg/S с полной площадью опоры: (50/0,001)/(4000/0,8) = 10. Давление каблука больше; обратное отношение равно 0,1.'],
 ['1.3',22,'Равновесие','Айсберг плавает в море. Плотность льда 917 кг/м³, морской воды 1024 кг/м³. Сколько процентов объёма выступает над водой? Округли до десятых.',10.4,'%','Вес льда равен весу вытесненной воды: доля под водой равна 917/1024. Над водой остаётся (1 − 917/1024) · 100% ≈ 10,4%.'],
 ['1.4',24,'Основы астрономии','Ниигата расположена на 334 км севернее горы Амаги на том же меридиане. Дуга от экватора до полюса равна 10 000 км. На сколько градусов различается высота Солнца при прохождении меридиана? Округли до целых.',3,'°','Дуге в 10 000 км соответствует 90°. Разность широт равна 90° · 334/10 000 ≈ 3°. В этих двух точках это и есть разность полуденных высот.'],
["1.5(1)", 26, "Механика", "Подъёмная сила крыла на единицу размаха описывается выражением F/W = kρᵃvᵇLᶜ. Здесь k безразмерно, ρ — плотность воздуха, v — скорость, L — хорда крыла. Определи показатель b методом размерностей.", 2, "без единиц", "[F/W] = MT⁻². В правой части степени массы, времени и длины равны a, −b и −3a+b+c. Приравняем показатели: a = 1, −b = −2, −3+2+c = 0. Следовательно, b = 2 и c = 1."],
["1.5(2)", 26, "Плотность", "При взлёте скорость самолёта 250 км/ч, на высоте 10 км — 900 км/ч. При одинаковой подъёмной силе и неизменных параметрах крыла найди отношение плотности воздуха на высоте к плотности у земли. Округли до тысячных.", 0.077, "без единиц", "При F = kρv²LW постоянство силы означает ρ₀v₀² = ρ₁v₁². Скорости заданы в одинаковых единицах: ρ₁/ρ₀ = (250/900)² ≈ 0,077. Это оценка по модели, а не табличная плотность атмосферы."],
["1.5(3)", 27, "Кинематика", "Длины модели в α раз больше исходных, времена — в β раз. Масштаб ускорения запишем как αβⁿ. Найди n.", -2, "без единиц", "Скорость имеет размерность L/T, её масштаб α/β. Ускорение имеет размерность L/T², его масштаб α/β². Поэтому показатель времени для скорости равен −1, а для ускорения n = −2."],
["1.5(4)", 27, "Кинематика", "Модель в 100 раз меньше настоящего объекта. Её свободное падение снимают при том же g. Какую долю обычной скорости воспроизведения надо выбрать, чтобы длительность падения на экране совпала с реальной?", 0.1, "без единиц", "Для падения из покоя h = gt²/2. При той же g время пропорционально √h. Модель падает за 1/10 настоящего времени. Чтобы растянуть запись в 10 раз, выбери скорость 0,1 от обычной."]
].map(([id,page,topic,q,key,unit,solution])=>({id,page,topic,key,unit,solution,raw:q+'|'+key+' '+unit,skill:'Расчёт',level:8}));
