const bookDrafts=new Map(), solvedBook=new Set();
function updateBookScore(){const out=document.querySelector('#book-score');if(out)out.textContent=`${solvedBook.size} / ${olympBookTasks.length}`}
function workbook(chapter='all'){
 const container=document.querySelector('#book-tasks');
 container.innerHTML=olympBookTasks.map((x,i)=>{
  if(chapter!=='all' && !x.id.startsWith(chapter+'.'))return '';
  const [q,...opts]=x.raw.split('|');
  const answer=x.unit?`<label>Ответ в ${x.unit}: <input name="answer" inputmode="decimal" autocomplete="off" required></label>`:
    `<fieldset><legend>Выбери один вариант</legend>${['Верно','Неверно'].map(v=>`<label class="multi-option"><input type="radio" name="answer" value="${opts.indexOf(v)}" required> ${v}</label>`).join('')}</fieldset>`;
  return `<details class="lesson"><summary><small>№ ${x.id} · PDF с. ${x.page}</small><b>${x.topic}</b></summary><p>${q}</p>${bookFigures[x.id]||chapterFigures[x.id.split('(')[0]]||''}<label>Черновик решения<textarea rows="3" data-draft="${i}" oninput="bookDrafts.set(${i},this.value)"></textarea></label><small>Запиши модель, закон и расчёт. Проверяется только итоговый ответ. Черновик хранится до перезагрузки страницы.</small><form onsubmit="checkBook(this,${i});return false">${answer} <button>Проверить</button><p role="status" aria-live="polite"></p></form><details><summary>Разберём решение</summary><p>${x.solution}</p></details></details>`;
 }).join('');
 for(const field of container.querySelectorAll?.('textarea[data-draft]')||[])field.value=bookDrafts.get(Number(field.dataset.draft))||'';
 updateBookScore();
 const cloud=document.querySelector('.cloud-case');if(cloud)cloud.hidden=chapter!=='all'&&chapter!=='1';
}
function checkBook(form,i){const v=form.elements.answer.value.trim().replace(',','.');const x=olympBookTasks[i];const valid=x.unit?/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(v):['0','1'].includes(v);const correct=x.unit?Number(v)===x.key:v==='0';if(valid&&correct){solvedBook.add(x.id);updateBookScore()}form.querySelector('[role=status]').textContent=!valid?(x.unit?'Введи число.':'Выбери один вариант'):correct?'Верно!':'Пока неверно. Попробуй ещё раз или открой разбор.'}
workbook();
